CREATE TABLE dbo.customers (
    customer_id INT NOT NULL,
    name NVARCHAR(200) NOT NULL,
    email NVARCHAR(200) NULL,
    city NVARCHAR(100) NULL,
    signup_date DATE NULL,
    description NVARCHAR(MAX) NULL DEFAULT 'End customer who places orders',
    CONSTRAINT pk_customers PRIMARY KEY (customer_id)
);

CREATE TABLE dbo.products (
    product_id INT NOT NULL,
    name NVARCHAR(200) NOT NULL,
    category NVARCHAR(100) NULL,
    price FLOAT NULL,
    stock_quantity INT NULL,
    created_at DATE NULL,
    CONSTRAINT pk_products PRIMARY KEY (product_id)
);

CREATE TABLE dbo.orders (
    order_id INT NOT NULL,
    customer_id INT NULL,
    order_date DATE NOT NULL,
    total_amount FLOAT NULL,
    status NVARCHAR(50) NULL,
    shipping_date DATE NULL,
    CONSTRAINT pk_orders PRIMARY KEY (order_id),
    CONSTRAINT fk_orders_customer_id FOREIGN KEY (customer_id) REFERENCES dbo.customers(customer_id)
);

CREATE TABLE dbo.order_items (
    item_id INT NOT NULL,
    order_id INT NULL,
    product_id INT NULL,
    quantity INT NULL,
    unit_price FLOAT NULL,
    discount FLOAT NULL,
    CONSTRAINT pk_order_items PRIMARY KEY (item_id),
    CONSTRAINT fk_order_items_order_id FOREIGN KEY (order_id) REFERENCES dbo.orders(order_id),
    CONSTRAINT fk_order_items_product_id FOREIGN KEY (product_id) REFERENCES dbo.products(product_id)
);

CREATE TABLE dbo.payments (
    payment_id INT NOT NULL,
    order_id INT NULL,
    amount FLOAT NULL,
    payment_method NVARCHAR(50) NULL,
    payment_date DATE NULL,
    status NVARCHAR(50) NULL,
    CONSTRAINT pk_payments PRIMARY KEY (payment_id),
    CONSTRAINT fk_payments_order_id FOREIGN KEY (order_id) REFERENCES dbo.orders(order_id)
);

CREATE TABLE dbo.reviews (
    review_id INT NOT NULL,
    product_id INT NULL,
    customer_id INT NULL,
    rating INT NULL,
    review_text NVARCHAR(MAX) NULL,
    review_date DATE NULL,
    CONSTRAINT pk_reviews PRIMARY KEY (review_id),
    CONSTRAINT fk_reviews_product_id FOREIGN KEY (product_id) REFERENCES dbo.products(product_id),
    CONSTRAINT fk_reviews_customer_id FOREIGN KEY (customer_id) REFERENCES dbo.customers(customer_id),
    CONSTRAINT ck_reviews_rating CHECK (rating BETWEEN 1 AND 5)
);
